cd /tmp/vally-eval-trial-JULp0X && mkdir -p tests/CheckoutPricing.UnitTests/Pricing src/CheckoutPricing.Application/Pricing
cat > tests/CheckoutPricing.UnitTests/Pricing/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application.Pricing;

namespace CheckoutPricing.UnitTests.Pricing;

public sealed class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var checkout = new CalculateCheckoutTotal();

        var total = checkout.Handle(new CheckoutRequest(CustomerTier.Gold, 100.00m));

        Assert.Equal(95.00m, total);
    }
}
E
cat > src/CheckoutPricing.Application/Pricing/CalculateCheckoutTotal.cs <<'E'
namespace CheckoutPricing.Application.Pricing;

public enum CustomerTier { Gold }

public sealed record CheckoutRequest(CustomerTier Tier, decimal Subtotal);

public sealed class CalculateCheckoutTotal
{
    public decimal Handle(CheckoutRequest request) => request.Subtotal;
}
E
dotnet test tests/CheckoutPricing.UnitTests --filter "FullyQualifiedName~GoldDiscountTests" --verbosity quiet 2>&1 | tail -20

